# shellcheck shell=bash disable=SC2034
# Settings and helpers shared by the VALAR scripts (setup.sh, submit_ladder.sh, curiosity_job.sh, collect.sh).
#
# Do not edit this file. Put your own values in hpc/valar/my_settings.sh (git does not track it), e.g.
#     ACCOUNT=my_group
#     GPU_TYPE=l40s
#     STORE=/scratch/users/$USER/curiosity-hpc
# A value set there replaces the default below.

VALAR_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
REPO=$(cd "$VALAR_DIR/../.." && pwd)
if [ -f "$VALAR_DIR/my_settings.sh" ]; then
    # shellcheck source=/dev/null
    source "$VALAR_DIR/my_settings.sh"
fi

# Where jobs run. VALAR's example job script uses partition, account and qos "ai"; `sinfo` shows yours.
PARTITION=${PARTITION:-ai}
ACCOUNT=${ACCOUNT:-ai}
QOS=${QOS:-ai}
# The GPU type as SLURM names it (sinfo -o "%20N %60G" lists them). Empty means any GPU, which can be a
# 16 GB Tesla T4: too small for the larger models. A 48 GB card (A40, L40S, RTX A6000) fits them all.
GPU_TYPE=${GPU_TYPE:-}
GPU_MEM_GB=${GPU_MEM_GB:-48}    # memory of one such GPU; decides how many GPUs a job asks for
CPUS=${CPUS:-8}
MAIL_USER=${MAIL_USER:-}        # an address for "job ended" mails; empty means no mails
# The Python environment, Ollama and the models: about 90 GB with every model of the ladder.
STORE=${STORE:-$HOME/curiosity-hpc}
PYTHON_MODULE=${PYTHON_MODULE:-anaconda3}   # loaded only when no Python 3.10 or newer is found
# Where runs are written: diaries, reports and logs.
RESULTS=${RESULTS:-$REPO/runs/valar}

# The size ladder: one model family, so that only the size changes, plus Mistral 7B as on the laptop.
LADDER=${LADDER:-"qwen2.5:3b qwen2.5:7b qwen2.5:14b qwen2.5:32b qwen2.5:72b mistral:7b-instruct"}
# One judge for every run: the judge is the measuring instrument and must not change with the model.
JUDGE_MODEL=${JUDGE_MODEL:-qwen2.5:32b}

PY=$STORE/venv/bin/python
OLLAMA=$STORE/ollama/bin/ollama

python_ok() {
    "$1" -c 'import sys; sys.exit(0 if sys.version_info >= (3, 10) else 1)' >/dev/null 2>&1
}

load_module() {
    # `module` is a shell function that batch shells do not always define.
    local had_u=0 status=0
    case $- in *u*) had_u=1 ;; esac
    set +u
    if ! type module >/dev/null 2>&1; then
        for init in /etc/profile.d/lmod.sh /etc/profile.d/modules.sh /usr/share/lmod/lmod/init/bash; do
            if [ -f "$init" ]; then
                # shellcheck source=/dev/null
                source "$init"
                break
            fi
        done
    fi
    if type module >/dev/null 2>&1; then
        module load "$1" || status=$?
    else
        status=1
    fi
    if [ "$had_u" = 1 ]; then set -u; fi
    return "$status"
}

free_port() {
    "$PY" -c 'import socket; s = socket.socket(); s.bind(("127.0.0.1", 0)); print(s.getsockname()[1]); s.close()'
}

slug() {
    echo "$1" | tr ':/' '--'
}

# Billions of parameters, read from a model name such as qwen2.5:72b (8 when the name does not say).
model_billions() {
    if [[ $1 =~ :([0-9]+(\.[0-9]+)?)b ]]; then echo "${BASH_REMATCH[1]}"; else echo 8; fi
}

# GPU memory (GB) a run needs: the size of each model as downloaded (from Ollama's manifest in STORE; without it
# about 0.66 GB per billion parameters, read from the name), plus the context of 8192 tokens and work space.
# The judge counts once more when it is another model.
memory_needed() {
    local python=$PY
    if [ ! -x "$python" ]; then python=python3; fi
    "$python" - "$STORE/models" "$@" <<'PYSIZE'
import json
import math
import re
import sys
from pathlib import Path

store, models = Path(sys.argv[1]), list(dict.fromkeys(sys.argv[2:]))


def downloaded_gb(model):
    name, _, tag = model.partition(":")
    path = store / "manifests" / "registry.ollama.ai" / (name if "/" in name else f"library/{name}") / (tag or "latest")
    try:
        return sum(layer.get("size", 0) for layer in json.loads(path.read_text())["layers"]) / 1e9
    except (OSError, ValueError, KeyError, TypeError):
        return None


def estimated_gb(model):
    found = re.search(r":(\d+(?:\.\d+)?)b", model)
    return 0.66 * (float(found.group(1)) if found else 8)


need = 0.0
for model in models:
    weights = downloaded_gb(model) or estimated_gb(model)
    need += weights + 3 + 0.04 * weights
print(math.ceil(need))
PYSIZE
}

# GPUs a run needs: a little of each card goes to the driver and to work space that grows with the cards.
gpus_needed() {
    awk -v need="$(memory_needed "$1" "$2")" -v per="$GPU_MEM_GB" 'BEGIN { n = int(need / (0.95 * per)); if (n * 0.95 * per < need) n++; if (n < 1) n = 1; print n }'
}

# Memory of the computer (GB) a job asks for: room to read the model files, at least 64 GB.
ram_needed() {
    awk -v need="$(memory_needed "$1" "$2")" 'BEGIN { n = int(need * 1.25 + 0.999); if (n < 64) n = 64; if (n > 480) n = 480; print n }'
}
